int minEatingSpeed(vector<int>& piles, int h) {
    int lo = 1, hi = *max_element(piles.begin(), piles.end());
    while (lo < hi) {
        int k = lo + (hi - lo) / 2; long long t = 0;
        for (int p : piles) t += (p + (long long)k - 1) / k;
        if (t <= h) hi = k; else lo = k + 1;
    }
    return lo;
}
